<?php
require dirname(__DIR__).'/vendor/autoload.php';
use App\Kernel;use App\Infrastructure\ConnectionFactory;use Symfony\Bundle\FrameworkBundle\KernelBrowser;
function check($ok,$message){if(!$ok){throw new RuntimeException('ECHEC : '.$message);}echo 'OK : '.$message."\n";}
$url=getenv('DATABASE_URL');if(!$url||!preg_match('~/_?[^/?]*_recette(?:\?|$)~',$url)||getenv('CANTINE_RECETTE_DESTRUCTIVE')!=='OUI'){throw new RuntimeException('Base recette dédiée requise.');}$db=ConnectionFactory::create($url);
check($db->fetchOne("SELECT COUNT(*) FROM ticket WHERE numero<>'ANCIEN' AND numero !~ '^[A-Z]{2}[0-9]{4}$'")==0,'nouveaux numéros : deux majuscules et quatre chiffres');check($db->fetchOne('SELECT COUNT(*) FROM ticket')==$db->fetchOne('SELECT COUNT(DISTINCT numero) FROM ticket'),'numéros uniques, anciens conservés');
$client=new KernelBrowser(new Kernel('test',true));$client->followRedirects();$client->catchExceptions(false);$db->executeStatement("UPDATE utilisateur SET email='ADMIN@RECETTE.TEST' WHERE role='ROLE_ADMIN'");$crawler=$client->request('GET','/connexion');$client->submit($crawler->selectButton('Se connecter')->form(['_username'=>'admin@recette.test','_password'=>'Recette!12345']));check($client->getResponse()->isSuccessful()&&!str_contains($client->getResponse()->getContent(),'Connexion refusée.'),'connexion administrateur indépendante de la casse');
$crawler=$client->request('GET','/tickets');check($crawler->filter('details#delivrer-ticket')->count()===1,'bloc délivrance repliable natif');check($crawler->filter('details#delivrer-ticket > form > .dish-grid input[name=plat_id]')->count()===2,'plats du jour proposés avant autres plats');
$crawler=$client->request('GET','/societe');$file=dirname(__DIR__).'/var/logo-recette.png';$img=imagecreatetruecolor(360,100);imagefill($img,0,0,imagecolorallocate($img,230,240,235));imagestring($img,5,50,42,'SOCIETE DE RECETTE',imagecolorallocate($img,30,70,45));imagepng($img,$file);unset($img);$form=$crawler->selectButton('Enregistrer la société')->form(['nom'=>'Société de recette','adresse'=>'Adresse test','telephone'=>'+225 0000000000','email'=>'societe@recette.test','identifiant_fiscal'=>'TEST-001']);$form['logo']->upload($file);$client->submit($form);check($db->fetchOne('SELECT nom FROM societe WHERE id=1')==='Société de recette','informations société enregistrées');check((bool)$db->fetchOne('SELECT logo FROM societe WHERE id=1'),'logo téléchargé');$client->request('GET','/societe/logo');check($client->getResponse()->isSuccessful()&&$client->getResponse()->headers->get('Content-Type')==='image/png','logo privé PNG accessible avec session');$tid=(int)$db->fetchOne('SELECT MIN(id) FROM ticket WHERE employe_id=1');foreach(['57','80'] as $width){$crawler=$client->request('GET','/imprimer/ticket/'.$tid.'?format='.$width);check($crawler->filter('body.format-'.$width)->count()===1&&$crawler->filter('img.company-logo')->count()===1,'ticket '.$width.' mm et logo');}$crawler=$client->request('GET','/badge/1');check($crawler->filter('img.company-logo')->count()===1,'logo sur badge');
// API mobile stateless : pas de cookie de la session web transmis.
$mobile=new KernelBrowser(new Kernel('test',true));$mobile->catchExceptions(true);$mobile->request('GET','/api/mobile/tickets');check($mobile->getResponse()->getStatusCode()===401,'API sans jeton refusée');$mobile->request('POST','/api/mobile/connexion',[],[],['CONTENT_TYPE'=>'application/json'],json_encode(['email'=>'test3@recette.test','mot_de_passe'=>'Recette!12345']));check($mobile->getResponse()->getStatusCode()===200,'connexion compte employé mobile');$data=json_decode($mobile->getResponse()->getContent(),true);$token=$data['jeton'];check(strlen($token)===64,'jeton mobile cryptographique');check($db->fetchOne('SELECT token_hash FROM mobile_token WHERE utilisateur_id=5')!==$token,'jeton jamais conservé en clair en base');$headers=['HTTP_AUTHORIZATION'=>'Bearer '.$token];$mobile->request('GET','/api/mobile/tickets',[],[],$headers);$body=json_decode($mobile->getResponse()->getContent(),true);check(count($body['tickets'])===2,'employé retrouve uniquement ses deux tickets');check($body['societe']['logo_disponible']===true&&$body['societe']['nom']==='Société de recette','identité société disponible au mobile');$other=(int)$db->fetchOne('SELECT id FROM ticket WHERE employe_id=2 LIMIT 1');$mobile->request('GET','/api/mobile/tickets/'.$other.'/qr',[],[],$headers);check($mobile->getResponse()->getStatusCode()===404,'QR autre employé interdit');$mobile->request('GET','/api/mobile/tickets/'.$tid.'/qr',[],[],$headers);check($mobile->getResponse()->getStatusCode()===200,'QR personnel mobile accessible');file_put_contents(dirname(__DIR__).'/var/qr-mobile.png',$mobile->getResponse()->getContent());file_put_contents(dirname(__DIR__).'/var/qr-mobile-payload.txt','CANTINE:T:'.$db->fetchOne('SELECT token FROM ticket WHERE id=?',[$tid]));$mobile->request('GET','/api/mobile/logo',[],[],$headers);check($mobile->getResponse()->getStatusCode()===200,'logo mobile authentifié');$mobile->request('POST','/api/mobile/deconnexion',[],[],$headers);check($mobile->getResponse()->getStatusCode()===200,'déconnexion mobile');$mobile->request('GET','/api/mobile/tickets',[],[],$headers);check($mobile->getResponse()->getStatusCode()===401,'jeton révoqué après déconnexion');
$mobile->request('POST','/api/mobile/connexion',[],[],['CONTENT_TYPE'=>'application/json'],json_encode(['email'=>'admin@recette.test','mot_de_passe'=>'Recette!12345']));check($mobile->getResponse()->getStatusCode()===401,'compte administrateur refusé dans API employé');
$mobile->request('POST','/api/mobile/connexion',[],[],['CONTENT_TYPE'=>'application/json'],json_encode(['email'=>'test3@recette.test','mot_de_passe'=>'Recette!12345']));$fresh=json_decode($mobile->getResponse()->getContent(),true)['jeton'];$saved=$db->fetchOne('SELECT mot_de_passe FROM utilisateur WHERE id=5');$db->executeStatement('UPDATE utilisateur SET mot_de_passe=? WHERE id=5',[$saved.'x']);$mobile->request('GET','/api/mobile/tickets',[],[],['HTTP_AUTHORIZATION'=>'Bearer '.$fresh]);check($mobile->getResponse()->getStatusCode()===401,'changement mot de passe invalide session mobile');$db->executeStatement('UPDATE utilisateur SET mot_de_passe=? WHERE id=5',[$saved]);$db->executeStatement('DELETE FROM mobile_token');
echo "RECETTE V3 TERMINEE\n";
